"use client";
import { useState } from "react";
import { logActivity, resetDb, useSlice } from "@/lib/biz/db";
import { LEAVE_ENTITLEMENT, ONBOARD_TEMPLATE, type Department, type EmpDoc, type Employee, type LeaveReq, type Onboarding, type Position, type Review } from "@/lib/biz/seed-hrm";
import { DEMO_TODAY, addDays, downloadCsv, emailOk, fmtDate, groupBy, money, moneyK, monthLabel, sum, tenureYears, uid, workingDays } from "@/lib/biz/util";
import type { Branding } from "@/lib/types";
import { AppProviders, AreaIn, Avatar, Badge, BarChart, BrandLogo, Btn, DataTable, DemoBadge, DemoLinks, Donut, Empty, FilterSelect, HBars, Kpi, KpiRow, Modal, PageHead, Panel, Progress, ResetButton, SelectIn, Segmented, Tabs, TextIn, Timeline, useConfirm, useToast, type Col } from "./kit";

/* People operations: a warm, centred workspace. Sections run along a header band; People is a faceted directory (cards, table or org tree) and every employee opens as a full profile page. */
const SECTIONS = [{ id: "people", label: "People" }, { id: "departments", label: "Departments" }, { id: "onboarding", label: "Onboarding" }, { id: "leave", label: "Leave" }, { id: "performance", label: "Performance" }, { id: "organization", label: "Organization" }];
const STATUSES: Employee["status"][] = ["Active", "Probation", "On leave", "Resigned"]; const TYPES: Employee["type"][] = ["Full-time", "Part-time", "Contract"];
const stTone = (s: string) => (s === "Active" ? "green" : s === "Probation" ? "amber" : s === "On leave" ? "blue" : "slate") as "green" | "amber" | "blue" | "slate";

export default function HrmApp({ branding }: { branding: Branding }) {
  const [hrm] = useSlice("hrm"); const [section, setSection] = useState("people"); const [empId, setEmpId] = useState<string | null>(null); const [find, setFind] = useState("");
  const pending = hrm.leave.filter((l) => l.status === "Pending").length; const onboarding = hrm.onboarding.filter((o) => o.items.some((i) => !i.done)).length;
  const hits = find.trim().length >= 2 ? hrm.employees.filter((e) => `${e.name} ${e.position} ${e.dept}`.toLowerCase().includes(find.trim().toLowerCase())).slice(0, 6) : [];
  const badge = (id: string) => (id === "leave" ? pending : id === "onboarding" ? onboarding : 0);
  return (
    <AppProviders className="bg-stone-50 text-slate-800" note="Demonstration HR software. All employees, salaries and reviews are fictional; no real personal data is used. Data is stored only in this browser (localStorage); there is no server or shared database.">
      <header className="no-print bg-slate-900 text-slate-100">
        <div className="mx-auto flex max-w-[1500px] flex-wrap items-center gap-x-5 gap-y-2 px-5 py-3">
          <BrandLogo branding={branding} height={30} />
          <div><h1 className="font-display text-xl font-semibold leading-tight text-white">NorthPeak People</h1><p className="text-sm text-slate-300">People operations · fictional employees only</p></div>
          <div className="relative ml-auto min-w-[220px] max-w-sm flex-1">
            <input type="search" value={find} onChange={(e) => setFind(e.target.value)} aria-label="Find an employee" placeholder="Find an employee…" className="w-full rounded-md border border-slate-600 bg-slate-800 px-3 py-2 text-[15px] text-white placeholder:text-slate-400" />
            {hits.length > 0 && <ul className="absolute left-0 right-0 z-40 mt-1 overflow-hidden rounded-lg border border-slate-200 bg-white text-slate-800 shadow-xl">{hits.map((e) => <li key={e.id}><button type="button" className="flex w-full items-center gap-2 px-3 py-2 text-left text-[15px] hover:bg-stone-50" onClick={() => { setEmpId(e.id); setFind(""); }}><Avatar name={e.name} size={26} />{e.name}<span className="ml-auto text-sm text-slate-500">{e.dept}</span></button></li>)}</ul>}
          </div>
          <DemoBadge /><ResetButton onReset={() => resetDb(["hrm"])} /><DemoLinks compact />
        </div>
        <nav aria-label="HR sections" className="mx-auto flex max-w-[1500px] flex-wrap gap-1 px-4">
          {SECTIONS.map((s) => <button key={s.id} type="button" data-nav={s.id} aria-current={section === s.id && !empId ? "page" : undefined} onClick={() => { setSection(s.id); setEmpId(null); }} className={`rounded-t-lg px-5 py-2.5 text-[16px] font-medium ${section === s.id && !empId ? "bg-stone-50 text-slate-900" : "text-slate-200 hover:bg-slate-800"}`}>{s.label}{badge(s.id) > 0 && <span className={`ml-2 rounded-full px-2 text-[13px] font-semibold ${section === s.id && !empId ? "bg-amber-200 text-amber-900" : "bg-amber-500 text-slate-900"}`}>{badge(s.id)}</span>}</button>)}
        </nav>
      </header>
      <main className="mx-auto w-full max-w-[1500px] min-w-0 flex-1 p-4 sm:p-6" id="app-main">
        {empId ? <Profile id={empId} back={() => setEmpId(null)} open={setEmpId} /> : <>
          {section === "people" && <People open={setEmpId} />}
          {section === "departments" && <DepartmentsSection />}
          {section === "onboarding" && <OnboardingScreen open={setEmpId} />}
          {section === "leave" && <LeaveScreen open={setEmpId} />}
          {section === "performance" && <Performance open={setEmpId} />}
          {section === "organization" && <OrganizationSection open={setEmpId} go={setSection} />}
        </>}
      </main>
    </AppProviders>
  );
}

const active = (e: Employee) => e.status !== "Resigned";
const approvedDays = (leave: LeaveReq[], empId: string, type: string) => sum(leave.filter((l) => l.empId === empId && l.type === type && l.status === "Approved" && l.from >= "2026-01-01"), (l) => l.days);
export const leaveBalance = (hrm: { leave: LeaveReq[]; leaveAdj: { empId: string; type: string; days: number }[] }, empId: string, type: string) => (LEAVE_ENTITLEMENT[type] ?? 0) + sum(hrm.leaveAdj.filter((a) => a.empId === empId && a.type === type), (a) => a.days) - approvedDays(hrm.leave, empId, type);

function Dash({ go, open }: { go(s: string): void; open(id: string): void }) {
  const [hrm] = useSlice("hrm"); const act = hrm.employees.filter(active);
  const byDept = Object.entries(groupBy(act, (e) => e.dept)).map(([label, v]) => ({ label, value: v.length })).sort((a, b) => b.value - a.value);
  const byType = Object.entries(groupBy(act, (e) => e.type)).map(([label, v]) => ({ label, value: v.length }));
  const onLeave = hrm.leave.filter((l) => l.status === "Approved" && l.from <= DEMO_TODAY && l.to >= DEMO_TODAY);
  const newHires = act.filter((e) => e.hireDate >= addDays(DEMO_TODAY, -365)); const openPos = sum(hrm.positions, (p) => p.openings);
  const avgTenure = act.length ? sum(act, (e) => tenureYears(e.hireDate)) / act.length : 0;
  const incompleteOb = hrm.onboarding.filter((o) => o.items.some((i) => !i.done));
  return (<>
    <PageHead title="HR dashboard" sub={`Workforce statistics calculated from ${hrm.employees.length} employee records. Demo date ${fmtDate(DEMO_TODAY)}.`} />
    <KpiRow><Kpi label="Headcount" value={act.length} sub={`${hrm.employees.length - act.length} resigned`} testid="kpi-headcount" onClick={() => go("directory")} /><Kpi label="On leave today" value={onLeave.length} sub={onLeave.map((l) => hrm.employees.find((e) => e.id === l.empId)?.name.split(" ")[0]).join(", ") || "nobody"} /><Kpi label="Pending leave requests" value={hrm.leave.filter((l) => l.status === "Pending").length} tone="amber" onClick={() => go("leave")} testid="kpi-pending" /><Kpi label="Open positions" value={openPos} onClick={() => go("positions")} /><Kpi label="Hired in last 12 months" value={newHires.length} /><Kpi label="Avg. tenure" value={`${avgTenure.toFixed(1)} yrs`} /></KpiRow>
    <div className="mt-4 grid gap-4 lg:grid-cols-3">
      <Panel title="Headcount by department" className="lg:col-span-2"><HBars items={byDept} /></Panel><Panel title="Employment type"><Donut slices={byType} center={<>{act.length}<br />people</>} /></Panel>
      <Panel title="Onboarding in progress" pad={false}><ul className="divide-y divide-slate-100">{incompleteOb.map((o) => { const e = hrm.employees.find((x) => x.id === o.empId)!; const d = o.items.filter((i) => i.done).length; return <li key={o.id} className="px-4 py-2.5"><button className="flex w-full items-center justify-between text-left text-sm" onClick={() => open(e.id)}><span>{e.name}</span><span className="text-xs text-slate-500">{d}/{o.items.length}</span></button><div className="mt-1"><Progress value={(d / o.items.length) * 100} /></div></li>; })}{incompleteOb.length === 0 && <li className="px-4 py-6 text-center text-sm text-slate-400">No active onboarding.</li>}</ul></Panel>
      <Panel title="Recent hires" pad={false} className="lg:col-span-2"><ul className="divide-y divide-slate-100">{[...act].sort((a, b) => b.hireDate.localeCompare(a.hireDate)).slice(0, 5).map((e) => <li key={e.id}><button className="flex w-full items-center gap-3 px-4 py-2 text-left text-sm hover:bg-slate-50" onClick={() => open(e.id)}><Avatar name={e.name} /><span className="flex-1"><span className="font-medium">{e.name}</span><span className="block text-xs text-slate-500">{e.position} · {e.dept}</span></span><span className="text-xs text-slate-500">{fmtDate(e.hireDate)}</span></button></li>)}</ul></Panel>
    </div></>);
}

/* ───────── Directory ───────── */

function EmployeeForm({ existing, onClose, onSave }: { existing?: Employee; onClose(): void; onSave(e: Omit<Employee, "id" | "notes">, onboard: boolean): void }) {
  const [hrm] = useSlice("hrm");
  const [f, setF] = useState({ name: existing?.name ?? "", email: existing?.email ?? "", phone: existing?.phone ?? "", dept: existing?.dept ?? hrm.departments[0]?.name ?? "", position: existing?.position ?? "", status: existing?.status ?? ("Probation" as Employee["status"]), type: existing?.type ?? ("Full-time" as Employee["type"]), hireDate: existing?.hireDate ?? DEMO_TODAY, salary: String(existing?.salary ?? ""), location: existing?.location ?? "Austin, US", managerId: existing?.managerId ?? "" });
  const [onboard, setOnboard] = useState(!existing); const [err, setErr] = useState<Record<string, string>>({});
  const positions = hrm.positions.filter((p) => p.dept === f.dept);
  const save = () => { const e: Record<string, string> = {}; if (f.name.trim().split(" ").length < 2) e.name = "Enter first and last name"; if (!emailOk(f.email)) e.email = "Enter a valid email address"; if (!f.position.trim()) e.position = "Choose or enter a position"; if (!(Number(f.salary) > 0)) e.salary = "Salary must be above 0"; if (!f.hireDate) e.hireDate = "Pick a hire date"; setErr(e); if (!Object.keys(e).length) onSave({ ...f, name: f.name.trim(), salary: Number(f.salary) }, onboard); };
  return (<Modal title={existing ? `Edit ${existing.name}` : "Add employee"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" onClick={save} testid="save-employee">Save employee</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Full name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} error={err.name} /><TextIn label="Work email" value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} error={err.email} />
      <SelectIn label="Department" value={f.dept} onChange={(e) => setF({ ...f, dept: e.target.value, position: "" })} options={hrm.departments.map((d) => d.name)} /><div><TextIn label="Position" list="hr-pos" value={f.position} onChange={(e) => setF({ ...f, position: e.target.value })} error={err.position} /><datalist id="hr-pos">{positions.map((p) => <option key={p.id} value={p.title} />)}</datalist></div>
      <SelectIn label="Status" value={f.status} onChange={(e) => setF({ ...f, status: e.target.value as Employee["status"] })} options={STATUSES} /><SelectIn label="Employment type" value={f.type} onChange={(e) => setF({ ...f, type: e.target.value as Employee["type"] })} options={TYPES} />
      <TextIn label="Hire date" type="date" value={f.hireDate} onChange={(e) => setF({ ...f, hireDate: e.target.value })} error={err.hireDate} /><TextIn label="Annual salary (USD)" type="number" value={f.salary} onChange={(e) => setF({ ...f, salary: e.target.value })} error={err.salary} />
      <TextIn label="Location" value={f.location} onChange={(e) => setF({ ...f, location: e.target.value })} /><SelectIn label="Manager" value={f.managerId} onChange={(e) => setF({ ...f, managerId: e.target.value })} options={[{ value: "", label: "No manager" }, ...hrm.employees.filter((x) => x.id !== existing?.id && active(x)).map((m) => ({ value: m.id, label: m.name }))]} /><TextIn label="Phone" value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })} /></div>
    {!existing && <label className="mt-3 flex items-center gap-2 text-sm"><input type="checkbox" checked={onboard} onChange={(e) => setOnboard(e.target.checked)} />Create an onboarding checklist for this employee</label>}</Modal>);
}

/* ───────── People: faceted directory ───────── */
function Facet({ title, options, value, onChange }: { title: string; options: { value: string; label: string; count: number }[]; value: string; onChange(v: string): void }) {
  return (<fieldset className="mb-5"><legend className="mb-1.5 text-base font-semibold text-slate-900">{title}</legend>
    <ul className="space-y-0.5">{[{ value: "", label: "All", count: options.reduce((a, o) => a + o.count, 0) }, ...options].map((o) => <li key={o.value}><label className="flex cursor-pointer items-center gap-2 rounded px-1.5 py-1 text-[15px] hover:bg-stone-100"><input type="radio" name={title} checked={value === o.value} onChange={() => onChange(o.value)} /><span className="flex-1">{o.label}</span><span className="text-sm text-slate-500 tabular-nums">{o.count}</span></label></li>)}</ul></fieldset>);
}
function OrgNode({ e, byMgr, open, depth }: { e: Employee; byMgr: Map<string, Employee[]>; open(id: string): void; depth: number }) {
  const kids = byMgr.get(e.id) ?? []; const [shown, setShown] = useState(depth < 2);
  return (<li>
    <div className="flex items-center gap-2 py-1">
      {kids.length > 0 ? <button type="button" aria-expanded={shown} aria-label={`${shown ? "Collapse" : "Expand"} ${e.name}'s team`} onClick={() => setShown(!shown)} className="flex h-7 w-7 items-center justify-center rounded border border-slate-300 bg-white text-sm hover:border-blue-500">{shown ? "−" : "+"}</button> : <span className="w-7" />}
      <button type="button" onClick={() => open(e.id)} className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-left hover:border-blue-500"><Avatar name={e.name} size={30} /><span><span className="block text-[15px] font-semibold text-slate-900">{e.name}</span><span className="block text-sm text-slate-600">{e.position} · {e.dept}</span></span></button>
      {kids.length > 0 && <span className="text-sm text-slate-500">{kids.length} direct report{kids.length === 1 ? "" : "s"}</span>}
    </div>
    {shown && kids.length > 0 && <ul className="ml-3 border-l-2 border-stone-200 pl-5">{kids.map((k) => <OrgNode key={k.id} e={k} byMgr={byMgr} open={open} depth={depth + 1} />)}</ul>}
  </li>);
}
function OrgTree({ open }: { open(id: string): void }) {
  const [hrm] = useSlice("hrm"); const act = hrm.employees.filter(active); const ids = new Set(act.map((e) => e.id));
  const byMgr = new Map<string, Employee[]>(); act.forEach((e) => { if (e.managerId && ids.has(e.managerId)) byMgr.set(e.managerId, [...(byMgr.get(e.managerId) ?? []), e]); });
  const roots = act.filter((e) => !e.managerId || !ids.has(e.managerId));
  return <ul data-testid="org-tree">{roots.map((r) => <OrgNode key={r.id} e={r} byMgr={byMgr} open={open} depth={0} />)}</ul>;
}
function People({ open }: { open(id: string): void }) {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const [dept, setDept] = useState(""); const [status, setStatus] = useState(""); const [type, setType] = useState(""); const [view, setView] = useState("cards"); const [q, setQ] = useState(""); const [sort, setSort] = useState("name"); const [form, setForm] = useState(false);
  const base = hrm.employees.filter((e) => !q || `${e.name} ${e.position} ${e.email} ${e.dept}`.toLowerCase().includes(q.toLowerCase()));
  const rows = base.filter((e) => (!dept || e.dept === dept) && (!status || e.status === status) && (!type || e.type === type)).sort((a, b) => (sort === "hire" ? b.hireDate.localeCompare(a.hireDate) : sort === "dept" ? a.dept.localeCompare(b.dept) || a.name.localeCompare(b.name) : a.name.localeCompare(b.name)));
  const count = (f: (e: Employee) => string, v: string) => base.filter((e) => f(e) === v).length;
  const cols: Col<Employee>[] = [{ key: "name", label: "Employee", render: (e) => <span className="flex items-center gap-2"><Avatar name={e.name} /><span><span className="block font-medium text-slate-900">{e.name}</span><span className="block text-sm text-slate-500">{e.email}</span></span></span>, value: (e) => e.name }, { key: "position", label: "Position" }, { key: "dept", label: "Department" }, { key: "status", label: "Status", render: (e) => <Badge tone={stTone(e.status)}>{e.status}</Badge> }, { key: "type", label: "Type" }, { key: "location", label: "Location" }, { key: "hireDate", label: "Hired", render: (e) => fmtDate(e.hireDate) }];
  const exportRows = () => downloadCsv("hr-employees", [["ID", "Name", "Email", "Department", "Position", "Status", "Type", "Hire date", "Salary", "Location"], ...rows.map((e) => [e.id, e.name, e.email, e.dept, e.position, e.status, e.type, e.hireDate, e.salary, e.location])]);
  return (<>
    <PageHead title="People" sub={`${rows.length} of ${hrm.employees.length} people. Use the filters on the left, or switch between cards, table and org tree.`} actions={<><Segmented label="Directory view" value={view} onChange={setView} options={[{ id: "cards", label: "Cards" }, { id: "table", label: "Table" }, { id: "org", label: "Org tree" }]} /><Btn onClick={exportRows} testid="export-employees">Export CSV ({rows.length})</Btn><Btn kind="primary" onClick={() => setForm(true)} testid="add-employee">+ Add employee</Btn></>} />
    <div className="grid gap-6 lg:grid-cols-[250px_1fr]">
      <aside aria-label="Directory filters" className="h-fit rounded-xl border border-stone-200 bg-white p-4 shadow-sm">
        <label className="mb-4 block"><span className="mb-1 block text-base font-semibold text-slate-900">Search</span><input type="search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Name, role, email…" aria-label="Search directory" className="w-full rounded-md border border-slate-300 px-3 py-2 text-[15px]" /></label>
        <Facet title="Department" value={dept} onChange={setDept} options={hrm.departments.map((d) => ({ value: d.name, label: d.name, count: count((e) => e.dept, d.name) }))} />
        <Facet title="Status" value={status} onChange={setStatus} options={STATUSES.map((s) => ({ value: s, label: s, count: count((e) => e.status, s) }))} />
        <Facet title="Employment type" value={type} onChange={setType} options={TYPES.map((s) => ({ value: s, label: s, count: count((e) => e.type, s) }))} />
        <label className="block"><span className="mb-1 block text-base font-semibold text-slate-900">Sort by</span><select aria-label="Sort directory" value={sort} onChange={(e) => setSort(e.target.value)} className="w-full rounded-md border border-slate-300 bg-white px-2 py-2 text-[15px]"><option value="name">Name</option><option value="dept">Department</option><option value="hire">Newest hire</option></select></label>
        {(dept || status || type || q) && <Btn small className="mt-4" onClick={() => { setDept(""); setStatus(""); setType(""); setQ(""); }}>Clear filters</Btn>}
      </aside>
      <div className="min-w-0">
        {view === "table" && <DataTable rows={rows} columns={cols} rowKey={(e) => e.id} onRow={(e) => open(e.id)} search={false} pageSize={12} testid="emp-table" />}
        {view === "cards" && (rows.length ? <ul className="grid gap-4 sm:grid-cols-2 2xl:grid-cols-3" data-testid="emp-cards">{rows.map((e) => <li key={e.id}><button type="button" onClick={() => open(e.id)} className="flex h-full w-full items-start gap-3 rounded-2xl border border-stone-200 bg-white p-4 text-left shadow-sm hover:border-blue-500"><Avatar name={e.name} size={52} /><span className="min-w-0 flex-1"><span className="block font-display text-lg font-semibold leading-tight text-slate-900">{e.name}</span><span className="block text-[15px] text-slate-600">{e.position}</span><span className="block text-sm text-slate-500">{e.dept} · {e.location}</span><span className="mt-2 flex flex-wrap gap-1.5"><Badge tone={stTone(e.status)}>{e.status}</Badge><Badge>{e.type}</Badge></span></span></button></li>)}</ul> : <Empty>No one matches these filters.</Empty>)}
        {view === "org" && <div className="rounded-xl border border-stone-200 bg-white p-4 shadow-sm"><OrgTree open={open} /></div>}
      </div>
    </div>
    {form && <EmployeeForm onClose={() => setForm(false)} onSave={(rec, onboard) => { const id = `e${Date.now().toString().slice(-6)}`; setHrm((s) => ({ ...s, employees: [...s.employees, { id, notes: [], ...rec }], onboarding: onboard ? [...s.onboarding, { id: uid("ob"), empId: id, startDate: rec.hireDate, items: ONBOARD_TEMPLATE.map(([task, owner]) => ({ id: uid("t"), task, owner, done: false })) }] : s.onboarding })); logActivity("HR", `Employee added: ${rec.name}`); toast(`${rec.name} added${onboard ? " with an onboarding checklist" : ""}`); setForm(false); }} />}</>);
}

/* ───────── Employee profile page ───────── */
const baseDocs = (e: Employee): EmpDoc[] => [{ id: `${e.id}-d1`, name: "Employment contract", kind: "Contract", date: e.hireDate }, { id: `${e.id}-d2`, name: "Right-to-work verification", kind: "Compliance", date: e.hireDate }, { id: `${e.id}-d3`, name: `Role description: ${e.position}`, kind: "Role", date: e.hireDate }];
function Profile({ id, back, open }: { id: string; back(): void; open(id: string): void }) {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const confirm = useConfirm(); const e = hrm.employees.find((x) => x.id === id);
  const [tab, setTab] = useState("overview"); const [edit, setEdit] = useState(false); const [note, setNote] = useState(""); const [docForm, setDocForm] = useState(false); const [review, setReview] = useState(false);
  if (!e) return <Empty>Employee not found. <Btn small onClick={back}>Back to people</Btn></Empty>;
  const mgr = hrm.employees.find((x) => x.id === e.managerId); const reports = hrm.employees.filter((x) => x.managerId === e.id); const leave = hrm.leave.filter((l) => l.empId === id).sort((a, b) => b.from.localeCompare(a.from)); const reviews = hrm.reviews.filter((r) => r.empId === id); const ob = hrm.onboarding.find((o) => o.empId === id);
  const docs = [...baseDocs(e), ...(e.docs ?? [])];
  const setStatus = (s: Employee["status"]) => { setHrm((st) => ({ ...st, employees: st.employees.map((x) => (x.id === id ? { ...x, status: s } : x)) })); logActivity("HR", `${e.name} status → ${s}`); toast(`Status changed to ${s}`); };
  const decide = (l: LeaveReq, s: "Approved" | "Rejected") => { setHrm((st) => ({ ...st, leave: st.leave.map((x) => (x.id === l.id ? { ...x, status: s, decidedBy: "e28" } : x)) })); logActivity("HR", `Leave ${s.toLowerCase()}: ${e.name} (${l.days} days)`); toast(`Leave ${s.toLowerCase()} for ${e.name}`, s === "Rejected" ? "amber" : "green"); };
  const activity = [{ id: "hire", at: e.hireDate, title: `Joined as ${e.position}`, sub: e.dept }, ...leave.map((l) => ({ id: l.id, at: l.submitted, title: `${l.type} leave ${l.status.toLowerCase()}`, sub: `${fmtDate(l.from)} – ${fmtDate(l.to)} (${l.days} days)` })), ...reviews.map((r) => ({ id: r.id, at: r.date, title: `${r.period} review ${r.status === "Completed" ? `completed · ${r.rating}/5` : "drafted"}`, sub: r.notes })), ...e.notes.map((n, i) => ({ id: `n${i}`, at: n.slice(0, 11), title: n.slice(13) || n, sub: "Note" }))].sort((a, b) => b.at.localeCompare(a.at));
  return (<>
    <p className="no-print mb-2"><button type="button" onClick={back} className="text-[15px] font-medium text-blue-700 hover:underline">← Back to the directory</button></p>
    <section className="mb-5 flex flex-wrap items-center gap-5 rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
      <Avatar name={e.name} size={84} />
      <div className="min-w-[220px] flex-1"><h2 className="font-display text-[32px] font-semibold leading-tight text-slate-900">{e.name}</h2><p className="text-lg text-slate-600">{e.position} · {e.dept}</p><p className="mt-1 flex flex-wrap items-center gap-2 text-[15px] text-slate-600"><Badge tone={stTone(e.status)}>{e.status}</Badge><Badge>{e.type}</Badge>{e.location} · {e.email} · {e.phone}</p></div>
      <div className="no-print flex flex-wrap items-center gap-2"><label className="flex items-center gap-2 text-sm text-slate-600">Status<select aria-label="Employee status" value={e.status} onChange={(ev) => setStatus(ev.target.value as Employee["status"])} className="rounded-md border border-slate-300 bg-white px-2 py-1.5 text-[15px] text-slate-800">{STATUSES.map((s) => <option key={s}>{s}</option>)}</select></label>
        <Btn onClick={() => setEdit(true)} testid="edit-employee">Edit</Btn><Btn onClick={() => downloadCsv(`employee-${e.id}`, [["Field", "Value"], ["Name", e.name], ["Email", e.email], ["Department", e.dept], ["Position", e.position], ["Status", e.status], ["Type", e.type], ["Hire date", e.hireDate], ["Location", e.location]])}>Export profile</Btn></div>
    </section>
    <Tabs value={tab} onChange={setTab} tabs={[{ id: "overview", label: "Overview" }, { id: "employment", label: "Employment" }, { id: "documents", label: "Documents", count: docs.length }, { id: "leave", label: "Leave", count: leave.length }, { id: "performance", label: "Performance", count: reviews.length }, { id: "activity", label: "Activity" }]} />
    <div className="mt-4">
      {tab === "overview" && <div className="grid gap-4 lg:grid-cols-3">
        <Panel title="Contact and reporting"><dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 text-[15px]"><dt className="text-slate-500">Email</dt><dd>{e.email}</dd><dt className="text-slate-500">Phone</dt><dd>{e.phone}</dd><dt className="text-slate-500">Manager</dt><dd>{mgr ? <button className="text-blue-700 hover:underline" onClick={() => open(mgr.id)}>{mgr.name}</button> : "—"}</dd><dt className="text-slate-500">Hired</dt><dd>{fmtDate(e.hireDate)} ({tenureYears(e.hireDate).toFixed(1)} years)</dd></dl></Panel>
        <Panel title="Leave balances"><ul className="space-y-1.5 text-[15px]">{["Annual", "Sick", "Parental", "Unpaid"].map((t) => <li key={t} className="flex justify-between"><span>{t}</span><span className="tabular-nums">{leaveBalance(hrm, id, t)} days left</span></li>)}</ul></Panel>
        <Panel title="Direct reports">{reports.length ? <ul className="space-y-1.5 text-[15px]">{reports.map((r) => <li key={r.id}><button className="text-blue-700 hover:underline" onClick={() => open(r.id)}>{r.name}</button> <span className="text-slate-500">· {r.position}</span></li>)}</ul> : <p className="text-[15px] text-slate-500">No direct reports.</p>}</Panel>
        {ob && <Panel title="Onboarding checklist" className="lg:col-span-3"><ChecklistView ob={ob} /></Panel>}</div>}
      {tab === "employment" && <Panel><dl className="grid grid-cols-[auto_1fr] gap-x-8 gap-y-2.5 text-[15px]"><dt className="text-slate-500">Department</dt><dd>{e.dept}</dd><dt className="text-slate-500">Position</dt><dd>{e.position}</dd><dt className="text-slate-500">Annual salary</dt><dd>{money(e.salary, "USD", 0)}</dd><dt className="text-slate-500">Employment type</dt><dd>{e.type}</dd><dt className="text-slate-500">Employee ID</dt><dd>{e.id}</dd></dl>
        <div className="mt-4 flex gap-2"><Btn small onClick={() => setEdit(true)}>Change department / position</Btn><Btn small kind="danger" onClick={async () => { if (await confirm(`Remove ${e.name} from the demo data?`)) { setHrm((s) => ({ ...s, employees: s.employees.filter((x) => x.id !== id), leave: s.leave.filter((l) => l.empId !== id), reviews: s.reviews.filter((r) => r.empId !== id), onboarding: s.onboarding.filter((o) => o.empId !== id) })); toast("Employee removed", "amber"); back(); } }}>Delete employee</Btn></div></Panel>}
      {tab === "documents" && <Panel title="Document records" actions={<Btn small onClick={() => setDocForm(true)} testid="add-doc">+ Add record</Btn>}><p className="mb-2 text-sm text-slate-600">Records only: this demo lists document names and dates. No file is uploaded or stored.</p>
        <ul className="divide-y divide-slate-100">{docs.map((d) => <li key={d.id} className="flex flex-wrap items-center gap-3 py-2 text-[15px]"><Badge>{d.kind}</Badge><span className="flex-1 font-medium">{d.name}</span><span className="text-slate-500">{fmtDate(d.date)}</span>{(e.docs ?? []).some((x) => x.id === d.id) && <Btn small kind="danger" aria-label={`Remove ${d.name}`} onClick={() => { setHrm((s) => ({ ...s, employees: s.employees.map((x) => (x.id === id ? { ...x, docs: (x.docs ?? []).filter((y) => y.id !== d.id) } : x)) })); toast("Record removed", "amber"); }}>Remove</Btn>}</li>)}</ul></Panel>}
      {tab === "leave" && <Panel pad={false}><ul className="divide-y divide-slate-100">{leave.map((l) => <li key={l.id} className="flex flex-wrap items-center gap-3 px-4 py-2.5 text-[15px]"><Badge>{l.type}</Badge><span>{fmtDate(l.from)} – {fmtDate(l.to)} ({l.days} days)</span><span className="text-slate-500">{l.reason}</span><span className="ml-auto flex items-center gap-2"><Badge tone={l.status === "Approved" ? "green" : l.status === "Rejected" ? "red" : "amber"}>{l.status}</Badge>{l.status === "Pending" && <><Btn small kind="primary" onClick={() => decide(l, "Approved")} aria-label={`Approve ${e.name}`}>Approve</Btn><Btn small kind="danger" onClick={() => decide(l, "Rejected")} aria-label={`Reject ${e.name}`}>Reject</Btn></>}</span></li>)}{leave.length === 0 && <li className="px-4 py-8 text-center text-[15px] text-slate-400">No leave recorded.</li>}</ul></Panel>}
      {tab === "performance" && <Panel title="Reviews and notes" actions={<Btn small onClick={() => setReview(true)} testid="profile-new-review">+ Add review / note</Btn>} pad={false}><ul className="divide-y divide-slate-100">{reviews.map((r) => <li key={r.id} className="px-4 py-3 text-[15px]"><div className="flex justify-between"><strong>{r.period}</strong><span>{r.status === "Completed" ? `${"★".repeat(r.rating)}${"☆".repeat(5 - r.rating)}` : <Badge tone="amber">Draft</Badge>}</span></div><p className="mt-1 text-slate-700">{r.notes || "No notes yet."}</p><p className="text-sm text-slate-500">Goals: {r.goals}</p></li>)}{reviews.length === 0 && <li className="px-4 py-8 text-center text-[15px] text-slate-400">No reviews yet.</li>}</ul></Panel>}
      {tab === "activity" && <Panel title="Activity and notes"><div className="mb-3 flex gap-2"><input aria-label="Add employee note" value={note} onChange={(ev) => setNote(ev.target.value)} placeholder="Add a note…" className="w-full rounded-md border border-slate-300 px-3 py-2 text-[15px]" /><Btn kind="primary" onClick={() => { if (!note.trim()) return toast("Write a note first", "red"); setHrm((s) => ({ ...s, employees: s.employees.map((x) => (x.id === id ? { ...x, notes: [`${fmtDate(DEMO_TODAY)}: ${note.trim()}`, ...x.notes] } : x)) })); setNote(""); toast("Note added"); }} testid="add-emp-note">Add</Btn></div>
        <Timeline items={activity.map((a) => ({ id: a.id, at: fmtDate(a.at), title: a.title, sub: a.sub }))} /></Panel>}
    </div>
    {edit && <EmployeeForm existing={e} onClose={() => setEdit(false)} onSave={(rec) => { setHrm((s) => ({ ...s, employees: s.employees.map((x) => (x.id === id ? { ...x, ...rec } : x)) })); logActivity("HR", `${rec.name} updated`); toast("Employee updated"); setEdit(false); }} />}
    {docForm && <DocForm onClose={() => setDocForm(false)} onSave={(d) => { setHrm((s) => ({ ...s, employees: s.employees.map((x) => (x.id === id ? { ...x, docs: [...(x.docs ?? []), { id: uid("doc"), ...d }] } : x)) })); toast("Document record added"); setDocForm(false); }} />}
    {review && <ReviewForm existing={{ empId: id } as Review} onClose={() => setReview(false)} onSave={(rec) => { setHrm((s) => ({ ...s, reviews: [{ id: uid("r"), date: DEMO_TODAY, ...rec }, ...s.reviews] })); logActivity("HR", `Review recorded for ${e.name}`); toast("Review saved"); setReview(false); }} />}</>);
}
function DocForm({ onSave, onClose }: { onSave(d: Omit<EmpDoc, "id">): void; onClose(): void }) {
  const [f, setF] = useState({ name: "", kind: "Certificate", date: DEMO_TODAY }); const [err, setErr] = useState("");
  return (<Modal title="Add document record" small onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-doc" onClick={() => { if (f.name.trim().length < 3) return setErr("Enter a document name (3+ characters)."); onSave({ ...f, name: f.name.trim() }); }}>Save record</Btn></>}>
    <div className="grid gap-3"><TextIn label="Document name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} /><SelectIn label="Type" value={f.kind} onChange={(e) => setF({ ...f, kind: e.target.value })} options={["Certificate", "Contract", "Compliance", "Policy", "Other"]} /><TextIn label="Date" type="date" value={f.date} onChange={(e) => setF({ ...f, date: e.target.value })} /></div><p className="mt-2 text-sm text-slate-600">Records only: no file is uploaded.</p>{err && <p role="alert" className="mt-1 text-sm text-red-600">{err}</p>}</Modal>);
}

/* ───────── Departments (with job positions) and Organization ───────── */
function DepartmentsSection() {
  const [v, setV] = useState("departments");
  return (<><div className="mb-3"><Segmented label="Department view" value={v} onChange={setV} options={[{ id: "departments", label: "Departments" }, { id: "positions", label: "Job positions" }]} /></div>{v === "departments" ? <Departments /> : <Positions />}</>);
}
function OrganizationSection({ open, go }: { open(id: string): void; go(s: string): void }) {
  const [v, setV] = useState("chart");
  return (<><PageHead title="Organization" sub="Reporting lines, workforce statistics and HR reports for the whole company." actions={<Segmented label="Organization view" value={v} onChange={setV} options={[{ id: "chart", label: "Org chart" }, { id: "workforce", label: "Workforce" }, { id: "reports", label: "Reports" }]} />} />
    {v === "chart" && <div className="rounded-xl border border-stone-200 bg-white p-5 shadow-sm"><OrgTree open={open} /></div>}
    {v === "workforce" && <Dash go={(s) => go(s === "directory" ? "people" : s === "positions" ? "departments" : s)} open={open} />}
    {v === "reports" && <HrReports />}</>);
}

function Departments() {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const confirm = useConfirm(); const [form, setForm] = useState<Department | "new" | null>(null);
  return (<><PageHead title="Departments" sub="Headcount and salary cost against each department's budget." actions={<Btn kind="primary" onClick={() => setForm("new")} testid="add-dept">+ New department</Btn>} />
    <ul className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{hrm.departments.map((d) => { const m = hrm.employees.filter((e) => e.dept === d.name && active(e)); const cost = sum(m, (e) => e.salary), head = hrm.employees.find((e) => e.id === d.headId); return (
      <li key={d.id}><Panel title={d.name} actions={<><Btn small onClick={() => setForm(d)}>Edit</Btn><Btn small kind="danger" onClick={async () => { if (m.length) return toast("Move or remove this department's employees first.", "red"); if (await confirm(`Delete department ${d.name}?`)) { setHrm((s) => ({ ...s, departments: s.departments.filter((x) => x.id !== d.id) })); toast("Department deleted", "amber"); } }}>Delete</Btn></>}>
        <p className="text-sm text-slate-500">Head: {head?.name ?? "—"} · {m.length} people</p><p className="mt-2 text-sm">Salary cost <strong>{money(cost, "USD", 0)}</strong> of {money(d.budget, "USD", 0)} budget</p><div className="mt-1"><Progress value={d.budget ? (cost / d.budget) * 100 : 0} tone={cost > d.budget ? "red" : cost > d.budget * 0.9 ? "amber" : "green"} label={`${d.name} budget used`} /></div></Panel></li>); })}</ul>
    {form && <DeptForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} onSave={(rec) => { if (form === "new") { setHrm((s) => ({ ...s, departments: [...s.departments, { id: uid("d"), ...rec }] })); toast("Department created"); } else { setHrm((s) => ({ ...s, departments: s.departments.map((x) => (x.id === form.id ? { ...x, ...rec } : x)), employees: s.employees.map((e) => (e.dept === form.name ? { ...e, dept: rec.name } : e)), positions: s.positions.map((p) => (p.dept === form.name ? { ...p, dept: rec.name } : p)) })); toast("Department updated"); } setForm(null); }} />}</>);
}
function DeptForm({ existing, onSave, onClose }: { existing?: Department; onSave(d: Omit<Department, "id">): void; onClose(): void }) {
  const [hrm] = useSlice("hrm"); const [f, setF] = useState({ name: existing?.name ?? "", headId: existing?.headId ?? "", budget: String(existing?.budget ?? "") }); const [err, setErr] = useState<Record<string, string>>({});
  return (<Modal title={existing ? "Edit department" : "New department"} small onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-dept" onClick={() => { const e: Record<string, string> = {}; if (f.name.trim().length < 2) e.name = "Enter a name"; else if (hrm.departments.some((d) => d.name.toLowerCase() === f.name.trim().toLowerCase() && d.id !== existing?.id)) e.name = "That department already exists"; if (!(Number(f.budget) > 0)) e.budget = "Budget must be above 0"; setErr(e); if (!Object.keys(e).length) onSave({ name: f.name.trim(), headId: f.headId, budget: Number(f.budget) }); }}>Save</Btn></>}>
    <div className="grid gap-3"><TextIn label="Department name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} error={err.name} /><SelectIn label="Department head" value={f.headId} onChange={(e) => setF({ ...f, headId: e.target.value })} options={[{ value: "", label: "None" }, ...hrm.employees.filter(active).map((e) => ({ value: e.id, label: e.name }))]} /><TextIn label="Annual salary budget (USD)" type="number" value={f.budget} onChange={(e) => setF({ ...f, budget: e.target.value })} error={err.budget} /></div></Modal>);
}
function Positions() {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const [form, setForm] = useState<Position | "new" | null>(null); const [dept, setDept] = useState("");
  const rows = hrm.positions.filter((p) => !dept || p.dept === dept); const filled = (p: Position) => hrm.employees.filter((e) => e.position === p.title && active(e)).length;
  const cols: Col<Position>[] = [{ key: "title", label: "Position", render: (p) => <span className="font-medium text-slate-900">{p.title}</span> }, { key: "dept", label: "Department" }, { key: "level", label: "Level" }, { key: "filled", label: "Filled", align: "right", value: filled }, { key: "openings", label: "Open", align: "right", render: (p) => (p.openings ? <Badge tone="amber">{p.openings} open</Badge> : "0") }, { key: "band", label: "Salary band", value: (p) => p.min, render: (p) => `${moneyK(p.min)} – ${moneyK(p.max)}` }, { key: "act", label: "", noSort: true, noCsv: true, render: (p) => <Btn small onClick={() => setForm(p)}>Edit</Btn> }];
  return (<><PageHead title="Job positions" actions={<Btn kind="primary" onClick={() => setForm("new")} testid="add-position">+ New position</Btn>} /><DataTable rows={rows} columns={cols} rowKey={(p) => p.id} exportName="hr-positions" toolbar={<FilterSelect label="Department" value={dept} onChange={setDept} options={hrm.departments.map((d) => d.name)} />} />
    {form && <PositionForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} onSave={(rec) => { if (form === "new") { setHrm((s) => ({ ...s, positions: [...s.positions, { id: uid("p"), ...rec }] })); toast("Position created"); } else { setHrm((s) => ({ ...s, positions: s.positions.map((x) => (x.id === form.id ? { ...x, ...rec } : x)) })); toast("Position updated"); } setForm(null); }} />}</>);
}
function PositionForm({ existing, onSave, onClose }: { existing?: Position; onSave(p: Omit<Position, "id">): void; onClose(): void }) {
  const [hrm] = useSlice("hrm"); const [f, setF] = useState({ title: existing?.title ?? "", dept: existing?.dept ?? hrm.departments[0]?.name ?? "", level: existing?.level ?? "Mid", openings: String(existing?.openings ?? 0), min: String(existing?.min ?? ""), max: String(existing?.max ?? "") }); const [err, setErr] = useState<Record<string, string>>({});
  return (<Modal title={existing ? "Edit position" : "New position"} onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-position" onClick={() => { const e: Record<string, string> = {}; if (f.title.trim().length < 2) e.title = "Enter a title"; if (!(Number(f.min) > 0)) e.min = "Enter a minimum"; if (!(Number(f.max) >= Number(f.min))) e.max = "Maximum must be at least the minimum"; if (!(Number(f.openings) >= 0)) e.openings = "0 or more"; setErr(e); if (!Object.keys(e).length) onSave({ title: f.title.trim(), dept: f.dept, level: f.level, openings: Number(f.openings), min: Number(f.min), max: Number(f.max) }); }}>Save</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Title" value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} error={err.title} /><SelectIn label="Department" value={f.dept} onChange={(e) => setF({ ...f, dept: e.target.value })} options={hrm.departments.map((d) => d.name)} /><SelectIn label="Level" value={f.level} onChange={(e) => setF({ ...f, level: e.target.value })} options={["Junior", "Mid", "Senior", "Lead"]} /><TextIn label="Open positions" type="number" value={f.openings} onChange={(e) => setF({ ...f, openings: e.target.value })} error={err.openings} /><TextIn label="Salary min" type="number" value={f.min} onChange={(e) => setF({ ...f, min: e.target.value })} error={err.min} /><TextIn label="Salary max" type="number" value={f.max} onChange={(e) => setF({ ...f, max: e.target.value })} error={err.max} /></div></Modal>);
}

/* ───────── Onboarding ───────── */
function ChecklistView({ ob }: { ob: Onboarding }) {
  const [, setHrm] = useSlice("hrm"); const toast = useToast(); const [task, setTask] = useState(""); const done = ob.items.filter((i) => i.done).length;
  return (<div><div className="mb-2 flex items-center gap-3"><Progress value={(done / Math.max(1, ob.items.length)) * 100} label="Onboarding progress" /><span className="text-xs tabular-nums text-slate-500" data-testid="ob-progress">{done}/{ob.items.length}</span></div>
    <ul className="divide-y divide-slate-100">{ob.items.map((i) => <li key={i.id} className="flex items-center gap-3 py-2 text-sm"><input type="checkbox" aria-label={i.task} checked={i.done} onChange={() => { setHrm((s) => ({ ...s, onboarding: s.onboarding.map((o) => (o.id === ob.id ? { ...o, items: o.items.map((x) => (x.id === i.id ? { ...x, done: !x.done } : x)) } : o)) })); }} /><span className={i.done ? "text-slate-400 line-through" : ""}>{i.task}</span><Badge>{i.owner}</Badge><button type="button" aria-label={`Remove ${i.task}`} className="ml-auto text-red-600" onClick={() => setHrm((s) => ({ ...s, onboarding: s.onboarding.map((o) => (o.id === ob.id ? { ...o, items: o.items.filter((x) => x.id !== i.id) } : o)) }))}>✕</button></li>)}</ul>
    <div className="mt-3 flex gap-2"><input aria-label="New onboarding task" value={task} onChange={(e) => setTask(e.target.value)} placeholder="Add a task…" className="w-full rounded-md border border-slate-300 px-2 py-1.5 text-sm" /><Btn onClick={() => { if (task.trim().length < 3) return toast("Describe the task", "red"); setHrm((s) => ({ ...s, onboarding: s.onboarding.map((o) => (o.id === ob.id ? { ...o, items: [...o.items, { id: uid("t"), task: task.trim(), owner: "HR", done: false }] } : o)) })); setTask(""); }} testid="add-ob-task">Add task</Btn></div></div>);
}
function OnboardingScreen({ open }: { open(id: string): void }) {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const [pick, setPick] = useState("");
  const without = hrm.employees.filter((e) => active(e) && !hrm.onboarding.some((o) => o.empId === e.id));
  return (<><PageHead title="Onboarding" sub="One checklist per new hire. Tick tasks off as they are completed." actions={<><select aria-label="Employee for new checklist" value={pick} onChange={(e) => setPick(e.target.value)} className="rounded-md border border-slate-300 bg-white px-2 py-1.5 text-sm"><option value="">Choose employee…</option>{without.map((e) => <option key={e.id} value={e.id}>{e.name}</option>)}</select>
    <Btn kind="primary" testid="create-checklist" onClick={() => { if (!pick) return toast("Choose an employee first", "red"); setHrm((s) => ({ ...s, onboarding: [...s.onboarding, { id: uid("ob"), empId: pick, startDate: DEMO_TODAY, items: ONBOARD_TEMPLATE.map(([task, owner]) => ({ id: uid("t"), task, owner, done: false })) }] })); logActivity("HR", `Onboarding checklist created for ${hrm.employees.find((e) => e.id === pick)?.name}`); toast("Checklist created from the standard template"); setPick(""); }}>Create checklist</Btn></>} />
    <div className="grid gap-4 lg:grid-cols-2">{hrm.onboarding.map((o) => { const e = hrm.employees.find((x) => x.id === o.empId); return <Panel key={o.id} title={<button className="hover:text-blue-700" onClick={() => e && open(e.id)}>{e?.name ?? "Unknown"} <span className="text-xs font-normal text-slate-500">· started {fmtDate(o.startDate)}</span></button>}><ChecklistView ob={o} /></Panel>; })}{hrm.onboarding.length === 0 && <Empty>No onboarding checklists yet.</Empty>}</div></>);
}

/* ───────── Leave ───────── */
function LeaveForm({ onClose, onSave }: { onClose(): void; onSave(l: Omit<LeaveReq, "id" | "status" | "submitted">): void }) {
  const [hrm] = useSlice("hrm"); const [f, setF] = useState({ empId: hrm.employees.find(active)?.id ?? "", type: "Annual" as LeaveReq["type"], from: addDays(DEMO_TODAY, 14), to: addDays(DEMO_TODAY, 18), reason: "" }); const [err, setErr] = useState("");
  const days = f.to >= f.from ? workingDays(f.from, f.to) : 0; const bal = f.empId ? leaveBalance(hrm, f.empId, f.type) : 0;
  return (<Modal title="Submit leave request" onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-leave" onClick={() => { if (f.to < f.from) return setErr("The end date cannot be before the start date."); if (days < 1) return setErr("The selected dates contain no working days."); if (f.type !== "Unpaid" && days > bal) return setErr(`Only ${bal} ${f.type.toLowerCase()} days are available; this request is for ${days}.`); if (hrm.leave.some((l) => l.empId === f.empId && l.status !== "Rejected" && l.from <= f.to && l.to >= f.from)) return setErr("This overlaps another request for the same employee."); onSave({ ...f, days }); }}>Submit request</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><SelectIn label="Employee" value={f.empId} onChange={(e) => setF({ ...f, empId: e.target.value })} options={hrm.employees.filter(active).map((e) => ({ value: e.id, label: e.name }))} /><SelectIn label="Leave type" value={f.type} onChange={(e) => setF({ ...f, type: e.target.value as LeaveReq["type"] })} options={["Annual", "Sick", "Parental", "Unpaid"]} /><TextIn label="From" type="date" value={f.from} onChange={(e) => setF({ ...f, from: e.target.value })} /><TextIn label="To" type="date" value={f.to} onChange={(e) => setF({ ...f, to: e.target.value })} /><AreaIn label="Reason" className="sm:col-span-2" value={f.reason} onChange={(e) => setF({ ...f, reason: e.target.value })} /></div>
    <p className="mt-2 text-sm text-slate-600">{days} working day{days === 1 ? "" : "s"} · balance available: {bal} days</p>{err && <p role="alert" className="mt-1 text-sm text-red-600">{err}</p>}</Modal>);
}
function LeaveScreen({ open }: { open(id: string): void }) {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const [tab, setTab] = useState("requests"); const [form, setForm] = useState(false); const [status, setStatus] = useState(""); const [month, setMonth] = useState("2026-03"); const [adj, setAdj] = useState<string | null>(null);
  const name = (id: string) => hrm.employees.find((e) => e.id === id)?.name ?? "?"; const rows = hrm.leave.filter((l) => !status || l.status === status);
  const decide = (l: LeaveReq, s: "Approved" | "Rejected") => { setHrm((st) => ({ ...st, leave: st.leave.map((x) => (x.id === l.id ? { ...x, status: s, decidedBy: "e28" } : x)) })); logActivity("HR", `Leave ${s.toLowerCase()}: ${name(l.empId)} (${l.days} days)`); toast(`Leave ${s.toLowerCase()} for ${name(l.empId)}`, s === "Rejected" ? "amber" : "green"); };
  const cols: Col<LeaveReq>[] = [{ key: "emp", label: "Employee", value: (l) => name(l.empId), render: (l) => <button className="font-medium text-blue-700 hover:underline" onClick={() => open(l.empId)}>{name(l.empId)}</button> }, { key: "type", label: "Type" }, { key: "from", label: "Dates", render: (l) => `${fmtDate(l.from)} – ${fmtDate(l.to)}` }, { key: "days", label: "Days", align: "right" }, { key: "reason", label: "Reason" }, { key: "status", label: "Status", render: (l) => <Badge tone={l.status === "Approved" ? "green" : l.status === "Rejected" ? "red" : "amber"}>{l.status}</Badge> },
    { key: "act", label: "", noSort: true, noCsv: true, render: (l) => l.status === "Pending" ? <div className="flex gap-1"><Btn small kind="primary" aria-label={`Approve ${name(l.empId)}`} onClick={() => decide(l, "Approved")}>Approve</Btn><Btn small kind="danger" aria-label={`Reject ${name(l.empId)}`} onClick={() => decide(l, "Rejected")}>Reject</Btn></div> : null }];
  const [y, m] = month.split("-").map(Number); const first = new Date(Date.UTC(y, m - 1, 1)); const dim = new Date(Date.UTC(y, m, 0)).getUTCDate(); const lead = (first.getUTCDay() + 6) % 7;
  const cells = Array.from({ length: lead + dim }, (_, i) => (i < lead ? null : `${month}-${String(i - lead + 1).padStart(2, "0")}`)); const shift = (d: number) => { const n = new Date(Date.UTC(y, m - 1 + d, 1)); setMonth(n.toISOString().slice(0, 7)); };
  const emps = hrm.employees.filter(active); const types = ["Annual", "Sick", "Parental", "Unpaid"];
  return (<><PageHead title="Leave management" sub="Requests, balances and the team leave calendar. Approving a request reduces the balance immediately." actions={<Btn kind="primary" onClick={() => setForm(true)} testid="new-leave">+ Submit leave request</Btn>} />
    <Tabs value={tab} onChange={setTab} tabs={[{ id: "requests", label: "Requests", count: hrm.leave.filter((l) => l.status === "Pending").length }, { id: "balances", label: "Balances" }, { id: "calendar", label: "Calendar" }]} />
    <div className="mt-3">
      {tab === "requests" && <DataTable rows={rows} columns={cols} rowKey={(l) => l.id} exportName="hr-leave-requests" defaultSort={{ key: "from", dir: -1 }} testid="leave-table" toolbar={<FilterSelect label="Status" value={status} onChange={setStatus} options={["Pending", "Approved", "Rejected"]} />} />}
      {tab === "balances" && <DataTable rows={emps} rowKey={(e) => e.id} exportName="hr-leave-balances" pageSize={12} testid="balance-table" columns={[{ key: "name", label: "Employee", value: (e) => e.name }, ...types.slice(0, 3).map((t) => ({ key: t, label: `${t} left`, align: "right" as const, value: (e: Employee) => leaveBalance(hrm, e.id, t) })), { key: "pend", label: "Pending days", align: "right", value: (e) => sum(hrm.leave.filter((l) => l.empId === e.id && l.status === "Pending"), (l) => l.days) }, { key: "adj", label: "", noSort: true, noCsv: true, render: (e) => <Btn small onClick={() => setAdj(e.id)} aria-label={`Adjust balance for ${e.name}`}>Adjust</Btn> }]} />}
      {tab === "calendar" && <Panel title={monthLabel(month)} actions={<><Btn small onClick={() => shift(-1)}>‹ Prev</Btn><Btn small onClick={() => shift(1)}>Next ›</Btn></>}><div className="grid grid-cols-7 gap-px overflow-hidden rounded-lg border border-slate-200 bg-slate-200 text-xs">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => <div key={d} className="bg-slate-50 p-1 text-center font-semibold text-slate-500">{d}</div>)}{cells.map((d, i) => <div key={i} className={`min-h-[64px] bg-white p-1 ${d === DEMO_TODAY ? "ring-2 ring-inset ring-blue-500" : ""}`}>{d && <><span className="text-slate-400">{Number(d.slice(8))}</span>{hrm.leave.filter((l) => l.status !== "Rejected" && l.from <= d && l.to >= d).slice(0, 3).map((l) => <div key={l.id} title={`${name(l.empId)}: ${l.type} (${l.status})`} className={`mt-0.5 truncate rounded px-1 ${l.status === "Pending" ? "bg-amber-100 text-amber-800" : "bg-blue-100 text-blue-800"}`}>{name(l.empId).split(" ")[0]}</div>)}</>}</div>)}</div><p className="mt-2 text-[11px] text-slate-500"><span className="text-blue-700">■</span> approved <span className="ml-2 text-amber-700">■</span> pending</p></Panel>}
    </div>
    {form && <LeaveForm onClose={() => setForm(false)} onSave={(rec) => { setHrm((s) => ({ ...s, leave: [{ id: uid("l"), status: "Pending", submitted: DEMO_TODAY, ...rec }, ...s.leave] })); logActivity("HR", `Leave request: ${name(rec.empId)} (${rec.days} days)`); toast("Leave request submitted for approval"); setForm(false); }} />}
    {adj && <AdjustForm empId={adj} onClose={() => setAdj(null)} onSave={(a) => { setHrm((s) => ({ ...s, leaveAdj: [...s.leaveAdj, { id: uid("adj"), empId: adj, ...a }] })); toast("Leave balance adjusted"); setAdj(null); }} />}</>);
}
function AdjustForm({ empId, onSave, onClose }: { empId: string; onSave(a: { type: string; days: number; reason: string }): void; onClose(): void }) {
  const [hrm] = useSlice("hrm"); const [f, setF] = useState({ type: "Annual", days: "1", reason: "" }); const [err, setErr] = useState("");
  return (<Modal title={`Adjust balance: ${hrm.employees.find((e) => e.id === empId)?.name}`} small onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-adjust" onClick={() => { const d = Number(f.days); if (!Number.isFinite(d) || d === 0) return setErr("Enter a non-zero number of days (negative to deduct)."); if (!f.reason.trim()) return setErr("A reason is required."); onSave({ type: f.type, days: d, reason: f.reason.trim() }); }}>Apply</Btn></>}>
    <div className="grid gap-3"><SelectIn label="Leave type" value={f.type} onChange={(e) => setF({ ...f, type: e.target.value })} options={["Annual", "Sick", "Parental", "Unpaid"]} /><TextIn label="Days (+ add, − deduct)" type="number" value={f.days} onChange={(e) => setF({ ...f, days: e.target.value })} /><TextIn label="Reason" value={f.reason} onChange={(e) => setF({ ...f, reason: e.target.value })} /></div>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}

/* ───────── Performance ───────── */
function Performance({ open }: { open(id: string): void }) {
  const [hrm, setHrm] = useSlice("hrm"); const toast = useToast(); const [form, setForm] = useState<Review | "new" | null>(null); const name = (id: string) => hrm.employees.find((e) => e.id === id)?.name ?? "?";
  const done = hrm.reviews.filter((r) => r.status === "Completed"); const avg = done.length ? sum(done, (r) => r.rating) / done.length : 0; const dist = [5, 4, 3, 2, 1].map((n) => ({ label: `${n} ★`, value: done.filter((r) => r.rating === n).length }));
  const cols: Col<Review>[] = [{ key: "emp", label: "Employee", value: (r) => name(r.empId), render: (r) => <button className="font-medium text-blue-700 hover:underline" onClick={() => open(r.empId)}>{name(r.empId)}</button> }, { key: "period", label: "Period" }, { key: "rating", label: "Rating", render: (r) => (r.status === "Completed" ? "★".repeat(r.rating) + "☆".repeat(5 - r.rating) : "—") }, { key: "reviewer", label: "Reviewer", value: (r) => name(r.reviewerId) }, { key: "status", label: "Status", render: (r) => <Badge tone={r.status === "Completed" ? "green" : "amber"}>{r.status}</Badge> }, { key: "notes", label: "Notes" }, { key: "act", label: "", noSort: true, noCsv: true, render: (r) => <Btn small onClick={() => setForm(r)} aria-label={`Edit review for ${name(r.empId)}`}>Edit</Btn> }];
  return (<><PageHead title="Performance reviews" actions={<Btn kind="primary" onClick={() => setForm("new")} testid="new-review">+ New review</Btn>} />
    <div className="mb-4 grid gap-4 lg:grid-cols-3"><KpiRow><Kpi label="Completed reviews" value={done.length} /><Kpi label="Average rating" value={avg ? avg.toFixed(1) : "—"} /><Kpi label="Drafts" value={hrm.reviews.length - done.length} /></KpiRow><Panel title="Rating distribution" className="lg:col-span-2"><HBars items={dist} /></Panel></div>
    <DataTable rows={hrm.reviews} columns={cols} rowKey={(r) => r.id} exportName="hr-reviews" testid="review-table" />
    {form && <ReviewForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} onSave={(rec) => { if (form === "new") { setHrm((s) => ({ ...s, reviews: [{ id: uid("r"), date: DEMO_TODAY, ...rec }, ...s.reviews] })); logActivity("HR", `Review recorded for ${name(rec.empId)}`); toast("Review saved"); } else { setHrm((s) => ({ ...s, reviews: s.reviews.map((x) => (x.id === form.id ? { ...x, ...rec } : x)) })); toast("Review updated"); } setForm(null); }} />}</>);
}
function ReviewForm({ existing, onSave, onClose }: { existing?: Review; onSave(r: Omit<Review, "id" | "date">): void; onClose(): void }) {
  const [hrm] = useSlice("hrm"); const [f, setF] = useState({ empId: existing?.empId ?? hrm.employees.find(active)?.id ?? "", period: existing?.period ?? "2026 H1", rating: String(existing?.rating || 3), reviewerId: existing?.reviewerId ?? "e28", notes: existing?.notes ?? "", goals: existing?.goals ?? "", status: existing?.status ?? ("Completed" as Review["status"]) }); const [err, setErr] = useState<Record<string, string>>({});
  return (<Modal title={existing ? "Edit review" : "New review"} onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-review" onClick={() => { const e: Record<string, string> = {}; if (f.status === "Completed" && f.notes.trim().length < 5) e.notes = "Add review notes (5+ characters) to complete a review"; if (!f.period.trim()) e.period = "Enter the review period"; setErr(e); if (!Object.keys(e).length) onSave({ ...f, rating: f.status === "Completed" ? Number(f.rating) : 0 }); }}>Save review</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><SelectIn label="Employee" value={f.empId} onChange={(e) => setF({ ...f, empId: e.target.value })} options={hrm.employees.filter(active).map((e) => ({ value: e.id, label: e.name }))} /><TextIn label="Review period" value={f.period} onChange={(e) => setF({ ...f, period: e.target.value })} error={err.period} /><SelectIn label="Reviewer" value={f.reviewerId} onChange={(e) => setF({ ...f, reviewerId: e.target.value })} options={hrm.employees.filter(active).map((e) => ({ value: e.id, label: e.name }))} /><SelectIn label="Status" value={f.status} onChange={(e) => setF({ ...f, status: e.target.value as Review["status"] })} options={["Draft", "Completed"]} />
      <SelectIn label="Rating (1–5)" value={f.rating} onChange={(e) => setF({ ...f, rating: e.target.value })} options={["1", "2", "3", "4", "5"]} disabled={f.status === "Draft"} /><div /><AreaIn label="Review notes" className="sm:col-span-2" value={f.notes} onChange={(e) => setF({ ...f, notes: e.target.value })} error={err.notes} /><AreaIn label="Goals for next period" className="sm:col-span-2" value={f.goals} onChange={(e) => setF({ ...f, goals: e.target.value })} /></div></Modal>);
}

/* ───────── Reports ───────── */
function HrReports() {
  const [hrm] = useSlice("hrm"); const act = hrm.employees.filter(active); const [tab, setTab] = useState("dept");
  const byDept = hrm.departments.map((d) => { const m = act.filter((e) => e.dept === d.name); return { name: d.name, head: m.length, cost: sum(m, (e) => e.salary), avg: m.length ? sum(m, (e) => e.salary) / m.length : 0, tenure: m.length ? sum(m, (e) => tenureYears(e.hireDate)) / m.length : 0 }; });
  const bands = [["< 1 yr", 0, 1], ["1–3 yrs", 1, 3], ["3–5 yrs", 3, 5], ["5+ yrs", 5, 99]].map(([label, lo, hi]) => ({ label: label as string, value: act.filter((e) => tenureYears(e.hireDate) >= (lo as number) && tenureYears(e.hireDate) < (hi as number)).length }));
  const byStatus = Object.entries(groupBy(hrm.employees, (e) => e.status)).map(([label, v]) => ({ label, value: v.length }));
  const leaveUse = ["Annual", "Sick", "Parental", "Unpaid"].map((t) => ({ label: t, value: sum(hrm.leave.filter((l) => l.type === t && l.status === "Approved" && l.from >= "2026-01-01"), (l) => l.days) }));
  const exp = () => downloadCsv("hr-department-report", [["Department", "Headcount", "Salary cost", "Average salary", "Average tenure (yrs)"], ...byDept.map((d) => [d.name, d.head, d.cost, Math.round(d.avg), d.tenure.toFixed(1)])]);
  return (<><PageHead title="HR reports" sub="Calculated from the current employee, leave and review records." actions={<Btn onClick={exp} testid="export-hr-report">Export department report CSV</Btn>} />
    <Tabs value={tab} onChange={setTab} tabs={[{ id: "dept", label: "By department" }, { id: "tenure", label: "Tenure" }, { id: "status", label: "Status" }, { id: "leave", label: "Leave taken" }]} />
    <div className="mt-3">{tab === "dept" && <Panel pad={false}><table className="w-full text-sm"><thead className="bg-slate-50 text-left text-[11px] uppercase text-slate-500"><tr><th className="p-2">Department</th><th className="p-2 text-right">Headcount</th><th className="p-2 text-right">Salary cost</th><th className="p-2 text-right">Avg. salary</th><th className="p-2 text-right">Avg. tenure</th></tr></thead><tbody>{byDept.map((d) => <tr key={d.name} className="border-t"><td className="p-2 font-medium">{d.name}</td><td className="p-2 text-right">{d.head}</td><td className="p-2 text-right tabular-nums">{money(d.cost, "USD", 0)}</td><td className="p-2 text-right tabular-nums">{money(d.avg, "USD", 0)}</td><td className="p-2 text-right">{d.tenure.toFixed(1)} yrs</td></tr>)}</tbody><tfoot className="border-t-2 bg-slate-50 font-semibold"><tr><td className="p-2">Total</td><td className="p-2 text-right">{sum(byDept, (d) => d.head)}</td><td className="p-2 text-right tabular-nums" data-testid="hr-total-cost">{money(sum(byDept, (d) => d.cost), "USD", 0)}</td><td colSpan={2} /></tr></tfoot></table></Panel>}
      {tab === "tenure" && <Panel title="Active employees by tenure"><BarChart ariaLabel="Tenure bands" data={bands.map((b) => ({ label: b.label, values: { people: b.value } }))} series={[{ key: "people", label: "Employees" }]} /></Panel>}
      {tab === "status" && <Panel title="All employees by status"><Donut slices={byStatus} center={<>{hrm.employees.length}<br />records</>} /></Panel>}
      {tab === "leave" && <Panel title="Approved leave days in 2026"><HBars items={leaveUse} /></Panel>}</div></>);
}

